import { createContext, useCallback, useContext, useReducer } from 'react'
import reducer from '../state/reducer.js'
import { BANK_ACTIONS } from '../state/actions.js'
// this is the context used by the all pages
export const BankAccountContext = createContext()
// provider provide the update context value
export const BankAccountContextProvider = (props) => {
  const [state, dispatch] = useReducer(reducer, {})

  const dispatchSetPolicyState = useCallback(
    (data) => {
      dispatch(BANK_ACTIONS.setPolicyState(data))
    },
    [dispatch]
  )
  const dispatchResetPolicyState = useCallback(
    (data) => {
      dispatch(BANK_ACTIONS.resetPolicyState(data))
    },
    [dispatch]
  )
  return (
    <BankAccountContext.Provider
      value={[
        state,
        dispatch,
        dispatchSetPolicyState,
        dispatchResetPolicyState,
      ]}
    >
      {props.children}
    </BankAccountContext.Provider>
  )
}
// use to read the value from the global state
export const useBankAccountContextValue = () => useContext(BankAccountContext)
