import { BankCardWrapper } from './index.style'
import { ACCOUNT_BANK, DELETE_RED } from '../../../../../../../images'
import { CustomText } from '../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import Pill from '../../../../../Policy/pages/TransactionList/container/components/Pill'
import { LANG_STRINGS } from '../../../../../../../lang'
import {
  setToLocalStorage,
  getFromLocalStorageData,
} from '../../../../../../../helpers/localstorage'
import { useEffect } from 'react'
import { useSendOtp } from '../../state/hooks/useBankAccounts'
import {
  useErrorContextValue,
  useResetError,
} from '@pasarpolis/common-react-hooks'
import { BANK_FORM_DATA } from '../../../../constants'
import { useHistory } from 'react-router'
import ToolTip from '../../../../../../../components/ToolTip'

function BankCard({ data, onOpenDeleteModal }) {
  const [{ sendOtpData = {} }, sendOtpRequest] = useSendOtp()
  const [{ sendOtpStatus }] = useErrorContextValue()
  const history = useHistory()
  const { resetError } = useResetError()
  const handleClick = () => {
    if (data.status === 'PENDING_OTP_VERIFICATION') {
      sendOtpRequest()
      setToLocalStorage(BANK_FORM_DATA, {
        bank_id: data.id,
      })
    }
  }
  useEffect(() => {
    if (sendOtpStatus === 'success') {
      const localData = getFromLocalStorageData(BANK_FORM_DATA)
      setToLocalStorage(BANK_FORM_DATA, {
        ...localData,
        operation_id: sendOtpData?.operation_id,
      })
      history.push('/bank-otp')
      resetError(['sendOtpStatus'])
    }
  }, [sendOtpStatus, sendOtpData, data.id, resetError, history])

  return (
    <BankCardWrapper className="bg-white flex-container" onClick={handleClick}>
      <img src={ACCOUNT_BANK} alt="bank icon" className="card-icon" />
      <div className="card-content">
        <CustomText
          color={AgentColorPallette.blackGrey}
          size="15px"
          bottom="0"
          weight={400}
        >
          {data.holder_name}
        </CustomText>
        <CustomText
          color={AgentColorPallette.black}
          size="10px"
          top="10px"
          weight={700}
        >
          {LANG_STRINGS.accountNo}:
        </CustomText>
        <CustomText color={AgentColorPallette.black} size="16px" weight={700}>
          {data.holder_id}
        </CustomText>
        <div className="flex-container gap margin-btm-16">
          <CustomText
            color={AgentColorPallette.black}
            size="14px"
            top="0"
            weight={400}
          >
            {JSON.parse(data.bank_account).display_name}
          </CustomText>
          <CustomText color={AgentColorPallette.black} size="14px" weight={400}>
            {data.branch_name}
          </CustomText>
        </div>
        {data.status === 'VERIFIED' && (
          <div className="status">
            <Pill
              color={AgentColorPallette.white}
              bgColor={AgentColorPallette.irishGreen}
              label={LANG_STRINGS.active}
            />
          </div>
        )}
        {data.status === 'PENDING_DOC_VERIFICATION' && (
          <div className="status">
            <Pill
              color={AgentColorPallette.white}
              bgColor={AgentColorPallette.fontGrey}
              label={LANG_STRINGS.verification}
            />
          </div>
        )}
        {data.status === 'PENDING_OTP_VERIFICATION' && (
          <div className="status">
            <Pill
              color={AgentColorPallette.white}
              bgColor={AgentColorPallette.fontGrey}
              label={LANG_STRINGS.pendingVerification}
            />
          </div>
        )}
        {data.status === 'REJECTED' && (
          <ToolTip
            dataView={
              <CustomText className="tooltip">{data.remarks}</CustomText>
            }
            className="tool-tip"
          >
            <div>
              <Pill
                color={AgentColorPallette.white}
                bgColor={AgentColorPallette.speechRed}
                label={LANG_STRINGS.rejected}
              />
            </div>
          </ToolTip>
        )}
      </div>
      <img
        src={DELETE_RED}
        alt="delete"
        className="icon"
        onClick={(e) => {
          e.stopPropagation()
          onOpenDeleteModal && onOpenDeleteModal(data)
        }}
      />
    </BankCardWrapper>
  )
}

export default BankCard
