import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useCallback, useEffect, useState } from 'react'
import { useHistory } from 'react-router-dom'
import { Button, Container, CustomText } from '../../../../../../components'
import LazyLoader from '../../../../../../components/LazyLoader/index'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { useGlobalContextValue } from '../../../../../../contextProvider/GlobalContext'
import { INFORMATION_NEW } from '../../../../../../images'
import { LANG_STRINGS } from '../../../../../../lang'
import Cookies from 'universal-cookie'
import { LOGIN_AS_GURDIAN } from '../../../../../../constants/cookies'
import BankCard from '../components/BankCard'
import BottomSheetSelect from '../components/BottomSheetSelect'
import EmptyPage from '../components/EmptyPage/index'
import GopayCard from '../components/GopayCard'
import { useBankAccountContextValue } from '../context'
import { useGetBankAccountList } from '../state/hooks/useBankAccounts'
import { BankAccountWrapper } from './index.style'
// BottomActionSheet is now used inside DeleteBottomSheet component
import DeleteBottomSheet from '../components/DeleteBottomSheet'

const cookies = new Cookies()

function BankAccountContainer() {
  const history = useHistory()
  const isGuardianAgentLogin = cookies.get(LOGIN_AS_GURDIAN)
  const [showBottom, setShowBottom] = useState(false)
  const [selected, setSelected] = useState('')
  const [bankAccounts, getBankAccountsRequest] = useGetBankAccountList()
  const [{ GET_BANK_ACCOUNT_LIST_LOADER }] = useLoaderContextValue()
  const [{ getAgentDetailData = {} }] = useGlobalContextValue()
  const [, , dispatchSetPolicyState] = useBankAccountContextValue()
  const [showDeleteModal, setShowDeleteModal] = useState(false)
  const [modalBankData, setModalBankData] = useState(null)

  useEffect(() => {
    getBankAccountsRequest()
  }, [getBankAccountsRequest])

  const handleBankDeleted = useCallback(() => {
    dispatchSetPolicyState({
      getBankAccountListData: {
        meta_data: {},
        data: [],
      },
    })
    getBankAccountsRequest()
  }, [getBankAccountsRequest, dispatchSetPolicyState])

  const handleOpenDeleteModal = useCallback((bank) => {
    setModalBankData(bank)
    setShowDeleteModal(true)
  }, [])

  const handleCloseDeleteModal = useCallback(() => {
    setShowDeleteModal(false)
    setModalBankData(null)
  }, [])

  const handleChange = (item) => {
    setSelected(item.id)
  }

  const handleCloseModal = useCallback(() => {
    setShowBottom((showBottom) => !showBottom)
  }, [])

  const handleSubmit = useCallback(() => {
    if (!selected) {
      return
    }
    if (selected === 'bank-account') {
      history.push('/bank-account/bankform')
    }
    if (selected === 'goPay') {
      history.push('/bank-account/gopayform')
    }
  }, [selected, history])

  return (
    <Container
      title={LANG_STRINGS.bankAccount}
      displayBackButton
      hideBottomTabs
      // showAddIcon={getAgentDetailData?.is_ktp_verified}
      // onAddIconClick={() => { setShowBottom(true) }}
      className="bg-white"
      loader={GET_BANK_ACCOUNT_LIST_LOADER}
      onBackClick={() => history.push('/profile')}
    >
      <BankAccountWrapper>
        {!getAgentDetailData?.is_ktp_verified && (
          <div className="warning-container">
            <div className="flex-container warning">
              <img src={INFORMATION_NEW} alt="information" className="icon" />
              <CustomText size="12px" color={AgentColorPallette.black} className="text">
                Nomor KTP belum diverifikasi, silahkan tunggu sampai proses verifikasi selesai.
              </CustomText>
            </div>
          </div>
        )}
        {bankAccounts?.getBankAccountListData?.data.every(
          (item) => item.status === 'PENDING_OTP_VERIFICATION'
        ) &&
          bankAccounts?.getBankAccountListData?.data.length > 0 && (
            <div className="warning-container">
              <div className="flex-container warning height-verify">
                <img src={INFORMATION_NEW} alt="information" className="icon" />
                <CustomText size="12px" color={AgentColorPallette.black} className="text">
                  Rekening bank anda sedang menunggu proses verifikasi. Silahkan lanjutkan ke
                  verifikasi OTP bila anda belum melakukan OTP verifikasi
                </CustomText>
              </div>
            </div>
          )}
        {GET_BANK_ACCOUNT_LIST_LOADER === false && (
          <div className="f-item">
            {bankAccounts?.getBankAccountListData?.data.length ? (
              bankAccounts?.getBankAccountListData?.data.map((item) =>
                JSON.parse(item.bank_account).display_name !== 'GO-PAY' ? (
                  <BankCard data={item} onOpenDeleteModal={handleOpenDeleteModal} />
                ) : (
                  <GopayCard data={item} />
                )
              )
            ) : (
              <EmptyPage
                ktp={!getAgentDetailData?.is_ktp_verified}
                onClick={() => {
                  setShowBottom(true)
                }}
              />
            )}
          </div>
        )}
        {
          <div className="footer-container">
            <Button
              disabled={!getAgentDetailData?.is_ktp_verified || !!isGuardianAgentLogin}
              onClick={() => history.push('/bank-account/bankform')}
            >
              Tambah Akun Bank
            </Button>
          </div>
        }
        {showBottom && (
          <BottomSheetSelect
            show={showBottom}
            onChange={handleChange}
            onClose={handleCloseModal}
            handleSubmit={handleSubmit}
          />
        )}
        <LazyLoader
          request={getBankAccountsRequest}
          pageSize={10}
          metaData={{
            total_pages: bankAccounts?.getBankAccountListData?.meta_data?.num_page,
            page: bankAccounts?.getBankAccountListData?.meta_data?.page,
          }}
          responseData={bankAccounts?.getBankAccountListData}
        />
        {showDeleteModal && modalBankData ? (
          <DeleteBottomSheet
            show={showDeleteModal}
            accountHolder={modalBankData.holder_name}
            accountNumber={modalBankData.holder_id}
            bankName={JSON.parse(modalBankData.bank_account).display_name}
            agentPhoneNo={getAgentDetailData?.phone_no}
            onClose={handleCloseDeleteModal}
            bankId={modalBankData.id}
            agentRef={getAgentDetailData.agent_ref}
            onBankDeleted={() => {
              handleCloseDeleteModal()
              handleBankDeleted()
            }}
          />
        ) : null}
      </BankAccountWrapper>
    </Container>
  )
}

export default BankAccountContainer
