import React, { useState } from 'react'
import { createPortal } from 'react-dom'
import { useDispatch } from 'react-redux'
import {
  DeleteBottomSheetContainer,
  MainIcon,
  MainTitle,
  BankDataContainer,
  BankAccountHolderName,
  BankNumberTitle,
  BankName,
  PinLabel,
  InputWrapper,
  DeleteBottomSheetWrapper,
} from './index.style'
import {
  DELETE_YELLOW,
  GREEN_CHECK_CIRCLE,
  RED_CROSS_CIRCLE,
  CLOSE_GREY,
} from '../../../../../../../images'
import PinInput from '../../../../../../../components/PinInput'
import { Button } from '../../../../../../../components'
import { hashString } from '../../../../../../../helpers/hashString'
import AuthActions from '../../../../../../../redux/auth/action'
import UserActions from '../../../../../../../redux/user/action'
import BottomActionSheet from '../../../../../../../components/BottomActionSheet'

const DeleteBottomSheet = ({
  show,
  accountHolder,
  accountNumber,
  bankName,
  agentPhoneNo,
  onClose,
  bankId,
  agentRef,
  onBankDeleted,
}) => {
  const [pin, setPin] = useState(null)
  const [status, setStatus] = useState('idle')
  const dispatch = useDispatch()

  const handleDelete = () => {
    if (!pin) return

    dispatch(
      AuthActions.validatePin(
        {
          payload: {
            phone_no: agentPhoneNo,
            pin: hashString(pin),
          },
        },
        {
          onSuccess: () => {
            dispatch(
              UserActions.deleteBankAccount(
                {
                  payload: {
                    agentId: agentRef,
                    bank_id: bankId,
                    pin: hashString(pin),
                  },
                },
                {
                  onSuccess: () => {
                    setStatus('success')
                    if (onBankDeleted) {
                      onBankDeleted()
                    }
                  },
                  onFailure: () => setStatus('failure'),
                }
              )
            )
          },
          onFailure: () => setStatus('failure'),
        }
      )
    )
  }

  const renderIcon = () => {
    switch (status) {
      case 'success':
        return <MainIcon src={GREEN_CHECK_CIRCLE} />
      case 'failure':
        return <MainIcon src={RED_CROSS_CIRCLE} />
      default:
        return <MainIcon src={DELETE_YELLOW} />
    }
  }

  if (!show) return null

  const sheet = (
    <BottomActionSheet
      show={show}
      onCloseSheet={onClose}
      backGroundColor="#F5F5F5"
    >
      <DeleteBottomSheetWrapper>
        <div className="bottom-sheet-header">
          <div className="bottom-sheet-title" />
          <div className="close-icon" onClick={onClose}>
            <img src={CLOSE_GREY} alt="close" />
          </div>
        </div>
        <DeleteBottomSheetContainer status={status}>
          {renderIcon()}
          <MainTitle>
            {status === 'success'
              ? 'Akun Bank Berhasil Dihapus'
              : status === 'failure'
                ? 'PIN Salah, Gagal Menghapus'
                : 'Hapus Akun Bank'}
          </MainTitle>

          {status === 'idle' && (
            <BankDataContainer>
              <BankAccountHolderName>{accountHolder}</BankAccountHolderName>
              <BankNumberTitle>No. Rekening:</BankNumberTitle>
              <MainTitle className="bank-number">{accountNumber}</MainTitle>
              <BankName>{bankName}</BankName>
            </BankDataContainer>
          )}

          {status === 'idle' && (
            <>
              <PinLabel>
                Masukkan 4 digit PIN Anda untuk konfirmasi penghapusan akun
                bank.
              </PinLabel>
              <InputWrapper>
                <PinInput onComplete={(value) => setPin(value)} />
              </InputWrapper>
            </>
          )}

          <Button
            variant="filled"
            onClick={status === 'idle' ? handleDelete : onClose}
            disabled={status === 'idle' && !pin}
          >
            {status === 'idle' ? 'Hapus' : 'Tutup'}
          </Button>
        </DeleteBottomSheetContainer>
      </DeleteBottomSheetWrapper>
    </BottomActionSheet>
  )

  return typeof document !== 'undefined' &&
    document.getElementById('bottom-sheet-portal')
    ? createPortal(sheet, document.getElementById('bottom-sheet-portal'))
    : null
}

export default DeleteBottomSheet
