import { useEffect, useRef, useState } from 'react'
import CircularLoader from '../CircularLoader'
import useLoadMoreData from '../../hooks/dataManagement/useLoadMoreData'
import { LazyLoaderStyle } from './index.style'

const getInitialListParams = (pageSize) => ({
  query: {
    page: 1,
    page_size: pageSize,
  },
})

const LazyLoader = ({ pageSize = 10, responseData, request, requestParams, metaData }) => {
  const listParams = useRef(getInitialListParams(pageSize))
  const [showLoader, setShowLoader] = useState(true)

  const { loadMoreRef } = useLoadMoreData({
    onPageEnd: () => {
      if (
        responseData?.data?.length >= pageSize &&
        listParams.current.query.page <= (metaData?.total_pages || metaData?.num_page)
      ) {
        const query = {
          ...listParams.current.query,
          ...requestParams,
        }
        request({ ...query })
      }
    },
  })

  useEffect(() => {
    if (metaData?.page) {
      listParams.current.query.page = metaData.page + 1
      if (listParams.current.query.page > (metaData?.total_pages || metaData?.num_page)) {
        setShowLoader(false)
      } else {
        setShowLoader(true)
      }
    }
  }, [responseData, metaData, setShowLoader, pageSize])

  return (
    <LazyLoaderStyle ref={loadMoreRef} showLoader={showLoader} className="infinite-loader">
      {Array.isArray(responseData?.data) && responseData.data.length >= pageSize && showLoader && (
        <CircularLoader isLoading />
      )}
    </LazyLoaderStyle>
  )
}
export default LazyLoader
