import { ConfigUrl } from '../../../../../configs/url'

export const PROFILE_ACTIONS = {

  UPDATE_PHONE_NUMBER_REQUEST: 'UPDATE_PHONE_NUMBER_REQUEST',
  UPDATE_PHONE_NUMBER: 'UPDATE_PHONE_NUMBER',

  UPDATE_PROFILE_REQUEST: 'UPDATE_PROFILE_REQUEST',
  UPDATE_PROFILE: 'UPDATE_PROFILE',

  RESEND_OTP_REQUEST: 'RESEND_OTP_REQUEST',
  RESEND_OTP: 'RESEND_OTP',

  UPDATE_AGENT_PHONE_NO_REQUEST: 'UPDATE_AGENT_PHONE_NO_REQUEST',
  UPDATE_AGENT_PHONE_NO: 'UPDATE_AGENT_PHONE_NO',

  updatePhoneNumber: (payload = {}) => ({
    type: PROFILE_ACTIONS.UPDATE_PHONE_NUMBER_REQUEST,
    payload: {
      ...payload,
      method: 'POST',
      body: payload,
      url: ConfigUrl.updatePhoneNumber
    }
  }),

  updateProfile: (payload = {}) => ({
    type: PROFILE_ACTIONS.UPDATE_PROFILE_REQUEST,
    payload: {
      ...payload,
      method: 'POST',
      body: payload,
      url: ConfigUrl.updateProfile
    }
  }),

  updateAgentPhoneNo: (payload = {}) => ({
    type: PROFILE_ACTIONS.UPDATE_AGENT_PHONE_NO_REQUEST,
    payload: {
      ...payload,
      method: 'POST',
      body: payload,
      url: ConfigUrl.updateAgentPhoneNo
    }
  }),

  resendOtp: (payload = {}) => ({
    type: PROFILE_ACTIONS.RESEND_OTP_REQUEST,
    payload: {
      ...payload,
      method: 'POST',
      body: payload,
      url: ConfigUrl.resendOtp
    }
  })
}
